import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class VisitLine {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "org.springframework.samples.petclinic.visits.VisitLine",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} date
   * @param {string} description
   * @param {string} ownerFirstName
   * @param {string} ownerLastName
   */
  constructor(date, description, ownerFirstName, ownerLastName) {
    this.#args = [date, description, ownerFirstName, ownerLastName];
    if (this.#args?.length === 0) {
      this.#instance = VisitLine.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : VisitLine.type.createInstance(...this.#args);
    }
  }
  /**
   * @returns {Promise<string>}
   */
  async getOwnerFirstName() {
    try {
      const returnObjectIC = await this.instance
        .invokeInstanceMethod("getOwnerFirstName")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<string>}
   */
  async getOwnerLastName() {
    try {
      const returnObjectIC = await this.instance
        .invokeInstanceMethod("getOwnerLastName")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<string>}
   */
  async getDate() {
    try {
      const returnObjectIC = await this.instance
        .invokeInstanceMethod("getDate")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<string>}
   */
  async getDescription() {
    try {
      const returnObjectIC = await this.instance
        .invokeInstanceMethod("getDescription")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
